// DEVDESK-629 step 8 (F2, F4): the level 1 line `Cached only` is now `May omit
// images`. What it says no longer rests on "the list is limited to the cache" (a
// claim nobody measured on a group) but on what was measured: a Nexus group may
// leave out the names of a member it cannot reach right now, without a word (200,
// fewer names), and a proxy that failed or was refused has told nothing.
//
// The mention follows the ROLE of the entry in its Nexus group (group, proxy,
// hosted, unknown), read from the repository type discovery stored for the member.

// typedMember is a discovered member of a Nexus group with the repository type
// discovery read for it ("" = unknown, as in a cache written before the type).
type typedMember struct{ prefix, typ string }

// typedMembers are members of "nx" the way discovery stores them for a path-routed
// group (the host of the HTTP port plus one prefix each), with their type.
func typedMembers(base string, ms ...typedMember) map[string]cache.RegistryGroupEntry {
	var members []cache.RegistryGroupMember
	for _, m := range ms {
		members = append(members, cache.RegistryGroupMember{Alias: m.prefix, URL: base, RepoPrefix: m.prefix, Type: m.typ})
	}
	return map[string]cache.RegistryGroupEntry{"nx": {Members: members}}
}

// typedConnectorMembers are members of "nx" on a connector of its own: the group's
// URL and no prefix, whatever the member, with their type.
func typedConnectorMembers(base string, ms ...typedMember) map[string]cache.RegistryGroupEntry {
	var members []cache.RegistryGroupMember
	for _, m := range ms {
		members = append(members, cache.RegistryGroupMember{Alias: m.prefix, URL: base, Type: m.typ})
	}
	return map[string]cache.RegistryGroupEntry{"nx": {Members: members}}
}

// typedNexusMembersModel opens the browser on the anonymous group "nx" whose
// discovered members are the given typed prefixes at base.
func typedNexusMembersModel(t *testing.T, base string, ms ...typedMember) Model {
	t.Helper()
	return modelWithGroups(t, []config.RegistryItem{anonymousNexusGroup(base)}, typedMembers(base, ms...))
}

func TestMemberRole(t *testing.T) {
	tests := []struct {
		typ  string
		want nexusRole
	}{
		{"hosted", nexusRoleHosted},
		{"proxy", nexusRoleProxy},
		// A group nested in a group may omit what its own members cannot reach.
		{"group", nexusRoleGroup},
		{"", nexusRoleUnknown},
		{"weird", nexusRoleUnknown},
		{"Proxy", nexusRoleUnknown},
	}
	for _, tt := range tests {
		t.Run(fmt.Sprintf("%q", tt.typ), func(t *testing.T) {
			if got := memberRole(tt.typ); got != tt.want {
				t.Errorf("memberRole(%q) = %v, want %v", tt.typ, got, tt.want)
			}
		})
	}
}

// H4: the rule, role by verdict. A group is mentioned whatever it answered (an
// answer of a group says nothing about what it left out) except when the catalog
// was not walked at all; a proxy only when it failed or was refused; a hosted
// repository never (it holds what it holds); an unknown role never (a cache with
// no type, or a type that could not be read: no mention is better than a false one).
func TestMayOmit(t *testing.T) {
	outcomes := []struct {
		name string
		oc   imagesearch.Outcome
	}{
		{"ok", imagesearch.Outcome{Verdict: imagesearch.VerdictOK}},
		{"ok partial", imagesearch.Outcome{Verdict: imagesearch.VerdictOK, Partial: true}},
		{"no result", imagesearch.Outcome{Verdict: imagesearch.VerdictNoResult}},
		{"failed", imagesearch.Outcome{Verdict: imagesearch.VerdictFailed}},
		{"refused", imagesearch.Outcome{Verdict: imagesearch.VerdictRefused}},
		{"skipped", imagesearch.Outcome{Verdict: imagesearch.VerdictNoResult, Skipped: true}},
	}
	roles := []struct {
		name string
		role nexusRole
		want map[string]bool
	}{
		{"group", nexusRoleGroup, map[string]bool{"ok": true, "ok partial": true, "no result": true, "failed": true, "refused": true}},
		{"proxy", nexusRoleProxy, map[string]bool{"failed": true, "refused": true}},
		{"hosted", nexusRoleHosted, nil},
		{"unknown", nexusRoleUnknown, nil},
	}
	for _, r := range roles {
		for _, o := range outcomes {
			t.Run(r.name+"/"+o.name, func(t *testing.T) {
				if got, want := mayOmit(r.role, o.oc), r.want[o.name]; got != want {
					t.Errorf("mayOmit(%s, %s) = %v, want %v", r.name, o.name, got, want)
				}
			})
		}
	}
}

// The words of the line are gone from the production code: the key, the help text,
// the field, the predicate. A comment that still says "cached only" would keep the
// old reading alive, so the scan covers comments too. It names file and line.
func TestNoCachedOnlyWordingLeft(t *testing.T) {
	entries, err := os.ReadDir(".")
	if err != nil {
		t.Fatal(err)
	}
	banned := []string{"Cached only", "cachedOnly", "CachedOnly", "cachedNoResultMark", "listsCacheOnly", "nothing in the cache"}
	scanned := 0
	for _, e := range entries {
		name := e.Name()
		if e.IsDir() || !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
			continue
		}
		scanned++
		src, err := os.ReadFile(name)
		if err != nil {
			t.Fatal(err)
		}
		for i, line := range strings.Split(string(src), "\n") {
			for _, w := range banned {
				if strings.Contains(line, w) {
					t.Errorf("%s:%d still says %q: %s", name, i+1, w, strings.TrimSpace(line))
				}
			}
		}
	}
	if scanned < 10 {
		t.Fatalf("scanned %d production files, the scan looks at the wrong directory", scanned)
	}
}

// The help says what the line means, in the words the user settled on, and no
// longer reads "(no result)" as "nothing in the cache".
func TestHelpExplainsMayOmitImages(t *testing.T) {
	const sentence = `May omit images (a Nexus proxy or group may not list images it cannot reach right now; "(no result)" does not mean the image is absent)`
	c := lvl1ImagesModel(t).GetHelpContent()

	var all strings.Builder
	header := ""
	for _, kb := range c.KeyBindings {
		all.WriteString(kb.Key + " " + kb.Description + "\n")
		if kb.Key == "Header (Browser images)" {
			header = kb.Description
		}
	}
	for _, s := range c.Sections {
		all.WriteString(s.Title + " " + s.Body + "\n")
	}
	if !strings.Contains(header, sentence) {
		t.Errorf("the Header (Browser images) help lacks %q:\n%s", sentence, header)
	}
	for _, gone := range []string{"Cached only", "nothing in the cache", "cached content"} {
		if strings.Contains(all.String(), gone) {
			t.Errorf("the help still says %q", gone)
		}
	}
}

// DEVDESK-308 (IS-14), step 1, renamed by DEVDESK-629 (F2): which picker entries
// belong to a Nexus group: the group, its discovered members and an entry declaring
// `parent:` towards a Nexus group (Q-B ii). It still drives catalogUnderPrefix; it
// no longer says anything about what an entry lists.
func TestIsNexusGroupOrMember(t *testing.T) {
	harbor := config.RegistryItem{Slug: "hb", Kind: config.KindGroup, Provider: config.ProviderHarbor, URL: "harbor.example.com"}
	generic := config.RegistryItem{Slug: "gn", Kind: config.KindGroup, Provider: config.ProviderGeneric, URL: "reg.example.com"}
	bySlug := map[string]config.RegistryItem{"nx": nexusGroup(), "hb": harbor, "gn": generic}

	tests := []struct {
		name string
		reg  config.RegistryItem
		want bool
	}{
		{"nexus group", nexusGroup(), true},
		{"declared parent to nexus group", config.RegistryItem{Slug: "m", Kind: config.KindRegistry, Parent: "nx"}, true},
		{"harbor group", harbor, false},
		{"generic group", generic, false},
		{"nexus registry without parent", config.RegistryItem{Slug: "n2", Kind: config.KindRegistry, Provider: config.ProviderNexus}, false},
		{"docker hub", config.RegistryItem{Slug: "hub", Kind: config.KindRegistry, URL: "docker.io"}, false},
		{"parent to generic group", config.RegistryItem{Slug: "m2", Kind: config.KindRegistry, Parent: "gn"}, false},
		{"parent to harbor group", config.RegistryItem{Slug: "m3", Kind: config.KindRegistry, Parent: "hb"}, false},
		{"parent to unknown slug", config.RegistryItem{Slug: "m4", Kind: config.KindRegistry, Parent: "zz"}, false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := isNexusGroupOrMember(tt.reg, bySlug); got != tt.want {
				t.Fatalf("isNexusGroupOrMember(%+v) = %v, want %v", tt.reg, got, tt.want)
			}
		})
	}
}

// H5: the role of an entry. A member discovered for a Nexus group takes the role of
// the type discovery read ("" or anything unexpected: unknown). The group itself,
// when nobody discovered it, is a group. An entry that declares a Nexus group as its
// parent takes the type of the discovered member with the SAME address (URL and
// prefix, exactly), else it is unknown. Nothing outside a Nexus group has a role.
func TestBuildEntriesSetsTheNexusRole(t *testing.T) {
	const host = "nexus.example.com"
	harbor := config.RegistryItem{Slug: "hb", Kind: config.KindGroup, Provider: config.ProviderHarbor, URL: "harbor.example.com", Alias: "hb"}
	generic := config.RegistryItem{Slug: "gn", Kind: config.KindGroup, Provider: config.ProviderGeneric, URL: "reg.example.com", Alias: "gn"}
	nexusPlain := config.RegistryItem{Slug: "n2", Kind: config.KindRegistry, Provider: config.ProviderNexus, URL: "n2.example.com", Alias: "n2"}
	hub := config.RegistryItem{Slug: "hub", Kind: config.KindRegistry, URL: "docker.io", Alias: "hub"}
	declaredAs := func(slug, url, prefix, parent string) config.RegistryItem {
		return config.RegistryItem{Slug: slug, Alias: slug, Kind: config.KindRegistry, Parent: parent, URL: url, RepoPrefix: prefix}
	}
	member := func(alias, url, prefix, typ string) cache.RegistryGroupMember {
		return cache.RegistryGroupMember{Alias: alias, URL: url, RepoPrefix: prefix, Type: typ}
	}
	nx := nexusGroup()
	nx.URL = host

	tests := []struct {
		name   string
		regs   []config.RegistryItem
		groups map[string]cache.RegistryGroupEntry
		want   map[string]nexusRole // Alias -> role
	}{
		{
			name:   "a group nobody discovered is a group, a declared member has no type to read",
			regs:   []config.RegistryItem{nx, harbor, generic, nexusPlain, hub, declaredAs("decl", "decl.example.com", "", "nx"), declaredAs("declg", "declg.example.com", "", "gn")},
			groups: nil,
			want: map[string]nexusRole{
				"nx": nexusRoleGroup, "hb": nexusRoleUnknown, "gn": nexusRoleUnknown, "n2": nexusRoleUnknown,
				"hub": nexusRoleUnknown, "decl": nexusRoleUnknown, "declg": nexusRoleUnknown,
			},
		},
		{
			name: "discovered members take the role of their type",
			regs: []config.RegistryItem{nx, harbor, generic},
			groups: map[string]cache.RegistryGroupEntry{
				"nx": {Members: []cache.RegistryGroupMember{
					member("hosted", host, "hosted", "hosted"),
					member("proxy", host, "proxy", "proxy"),
					member("nested", host, "nested", "group"),
					member("old", host, "old", ""),
					member("odd", host, "odd", "weird"),
				}},
				"hb": {Members: []cache.RegistryGroupMember{member("hb-a", "harbor.example.com", "", "proxy")}},
				"gn": {Members: []cache.RegistryGroupMember{member("gn-a", "reg.example.com", "", "proxy")}},
			},
			want: map[string]nexusRole{
				"hosted": nexusRoleHosted, "proxy": nexusRoleProxy, "nested": nexusRoleGroup,
				"old": nexusRoleUnknown, "odd": nexusRoleUnknown,
				// A member of a group that is not Nexus has no Nexus type to read.
				"hb-a": nexusRoleUnknown, "gn-a": nexusRoleUnknown,
			},
		},
		{
			name: "a declared entry takes the type of the discovered member at its exact address",
			regs: []config.RegistryItem{
				nx,
				declaredAs("d-proxy", host, "docker-proxy", "nx"),
				declaredAs("d-hosted", host, "docker-hosted", "nx"),
				declaredAs("d-nomatch", host, "docker-other", "nx"),
				declaredAs("d-noprefix", host, "", "nx"),
				declaredAs("d-otherhost", "other.example.com", "docker-proxy", "nx"),
				declaredAs("d-case", "NEXUS.example.com", "docker-proxy", "nx"),
				declaredAs("d-generic", host, "docker-proxy", "gn"),
			},
			groups: map[string]cache.RegistryGroupEntry{
				"nx": {Members: []cache.RegistryGroupMember{
					member("docker-proxy", host, "docker-proxy", "proxy"),
					member("docker-hosted", host, "docker-hosted", "hosted"),
				}},
			},
			want: map[string]nexusRole{
				"docker-proxy": nexusRoleProxy, "docker-hosted": nexusRoleHosted,
				"d-proxy": nexusRoleProxy, "d-hosted": nexusRoleHosted,
				"d-nomatch": nexusRoleUnknown, "d-noprefix": nexusRoleUnknown,
				"d-otherhost": nexusRoleUnknown, "d-case": nexusRoleUnknown,
				"d-generic": nexusRoleUnknown,
			},
		},
		{
			name: "a discovered member with no type leaves the declared entry unknown",
			regs: []config.RegistryItem{nx, declaredAs("d-proxy", host, "docker-proxy", "nx")},
			groups: map[string]cache.RegistryGroupEntry{
				"nx": {Members: []cache.RegistryGroupMember{member("docker-proxy", host, "docker-proxy", "")}},
	return fmt.Sprintf("+%d", len(names))
}

// searchSummary is what the level 1 header says about the lot, names in form order.
type searchSummary struct {
	Pending     int      // in the live lot, no answer yet
	Interrupted []string // the lot was abandoned (→) before they answered
	Failed      []string
	Refused     []string
	Partial     []string // ok or no result, cut at a cap
	MayOmit     []string // a Nexus group or proxy that may not list every image (DEVDESK-629)
	NoResult    []string // answered, nothing matches (Skipped excluded)
	Skipped     []string // catalog not walked: query too short
}

// noResultMark follows a name on the May omit images line when that registry
// answered with no result. It does not mean the image is absent: the registry may
// have left out what it could not reach.
const noResultMark = " (no result)"

// mayOmit says whether a registry in this role, with this outcome, is mentioned on
// the May omit images line. A Nexus group may leave out what a member cannot reach
// right now, whatever it answered; a proxy only when it failed or was refused (it
// told nothing); a hosted repository holds what it holds; an unknown role is never
// mentioned (no mention is better than a false one). A catalog that was not walked
// (Skipped) is never mentioned: nothing was listed.
func mayOmit(role nexusRole, oc imagesearch.Outcome) bool {
	if oc.Skipped {
		return false
	}
	switch role {
	case nexusRoleGroup:
		return true
	case nexusRoleProxy:
		return oc.Verdict == imagesearch.VerdictFailed || oc.Verdict == imagesearch.VerdictRefused
	}
	return false
}

// summarizeSearch sorts the lot's keys into classes. Pure; names are label(key),
// in the order of keys. role gives the Nexus role of each key. A key that mayOmit
// goes to MayOmit: one that answered with no result carries noResultMark and is
// not in NoResult; one that failed or was refused stays on its own line too, with
// no mark; a partial one also goes to Partial.
func summarizeSearch(keys []string, outcomes map[string]imagesearch.Outcome, live bool,
	label func(key string) string, role func(key string) nexusRole) searchSummary {
