//
// Three outcomes, one write at most, one instant (msg.At) shared by the disk and
// the model: a listing (even an empty one) is written and clears any refusal; a
// refusal (*registrymgr.MembersRefusedError) is written beside the listing, which
// it never touches (a 401 or 403, or the 404 Nexus answers with "Repository not
// found"); any other error (network, deadline, a 404 other than Nexus's
// Repository not found, 5xx, unreadable reply) writes nothing, because not
// being able to ask says nothing about the group.
func detectRegistryGroupCmd(reg config.RegistryItem, password string) tea.Cmd {
	return func() tea.Msg {
		ctx, cancel := context.WithTimeout(context.Background(), groupDetectTimeout)
		defer cancel()

		username := reg.Username
		// D12: a registry the user marked anonymous is probed anonymously.
		// Docker keys credentials by host, so without this gate the credentials
		// stored for any registry on that host went out to all of them — which,
		// for a Nexus instance, is every repository it serves.
		if config.UsesCredentials(config.ResolveAuthMode(reg, nil)) {
			username, password = discoveryCreds(reg, username, password)
		} else {
			username, password = "", ""
		}

		info := registrymgr.RegistryInfo{
			Provider:      reg.Provider,
			URL:           reg.URL,
			ManagementURL: reg.ManagementURL,
			Username:      username,
			Password:      password,
		c, err := cache.NewRegistryGroupCache()
		if err != nil {
			log.Printf("ERROR [oci_resources] open the registry group cache: %v", err)
			return RegistryGroupCacheLoadedMsg{}
		}
		return RegistryGroupCacheLoadedMsg{Entries: c.GetAll(), Refusals: c.Refusals()}
	}
}

// discoveryCreds completes the credentials the group probe authenticates with.
// A username or password already stated outranks anything stored: it is the more
// recent statement of intent, and it is how a wrong stored credential is worked
// around.
//
// The probe goes to the management URL when there is one. When that host is not
// the registry's, only a login stored for the management host may go there: the
// registry host's login belongs to that host, and sending it to another one hands
// it a password it was never given (DEVDESK-629, M1).
func discoveryCreds(reg config.RegistryItem, username, password string) (string, string) {
	if reg.ManagementURL != "" && !sameHost(reg.URL, reg.ManagementURL) {
		if password != "" {
			return username, password
		}
		return completeFromStored(reg.ManagementURL, username, password)
	}

	username, password = completeFromStored(reg.URL, username, password)
	if reg.ManagementURL == "" || password != "" {
		return username, password
	}
	return completeFromStored(reg.ManagementURL, username, password)
}

// completeFromStored fills what is missing of username and password from the
// login the engine holds for registryURL. The management URL names a repository
// path and Docker stores logins by host, so GetStoredCreds reads it through its
// host key.
func completeFromStored(registryURL, username, password string) (string, string) {
	storedUser, REDACTED, ok := docker.GetStoredCreds(registryURL)
	if !ok {
		return username, password
	}
	if username == "" {
		username = storedUser
	}
	if password == "" {
		password = REDACTED
	}
	return username, password
}

